create extension if not exists pgcrypto;
create table users_profile(id uuid primary key references auth.users(id), email text not null unique, full_name text, role text not null default 'requester' check(role in('requester','approver','admin')), department text, created_at timestamptz default now());
create sequence pr_number_seq;
create or replace function generate_pr_number() returns text language plpgsql as $$ begin return 'PR-'||to_char(now(),'YYYY')||'-'||lpad(nextval('pr_number_seq')::text,6,'0'); end; $$;
create table purchase_headers(id uuid primary key default gen_random_uuid(), pr_number varchar unique not null default generate_pr_number(), requester_id uuid not null references auth.users(id), requester_email text not null, department text not null, cost_center text not null, required_date date not null, vendor_name text not null, currency char(3) not null default 'USD', remarks text default '', status text not null default 'DRAFT', current_level int not null default 0, created_at timestamptz default now(), updated_at timestamptz default now(), submitted_at timestamptz, approved_at timestamptz, cancelled_at timestamptz, clarification_comments text);
create table purchase_line_items(id uuid primary key default gen_random_uuid(), header_id uuid not null references purchase_headers(id) on delete cascade, line_no int not null check(line_no between 1 and 100), item_description text not null, specification text default '', qty numeric(14,3) not null check(qty>0), uom text not null, estimated_price numeric(14,2) not null check(estimated_price>=0), tax_percent numeric(5,2) not null default 0, discount_percent numeric(5,2) not null default 0, total_amount numeric(14,2) generated always as ((qty*estimated_price)-((qty*estimated_price)*discount_percent/100)+((qty*estimated_price)*tax_percent/100)) stored, remarks text default '', unique(header_id,line_no));
create table approval_logs(id uuid primary key default gen_random_uuid(), header_id uuid not null references purchase_headers(id), level int not null default 0, action text not null, previous_status text, new_status text not null, approver_email text, comments text, timestamp timestamptz default now(), ip_address inet, user_agent text);
create table approval_matrix(id uuid primary key default gen_random_uuid(), department text not null, min_amount numeric(14,2) not null, max_amount numeric(14,2) not null, approval_level int not null check(approval_level between 1 and 3), approver_email text not null, sequence int not null, unique(department,approval_level,sequence));
create table email_queue(id uuid primary key default gen_random_uuid(), header_id uuid references purchase_headers(id), recipient text not null, subject text not null, html text not null, status text not null default 'queued', token_jti uuid, sent_at timestamptz, created_at timestamptz default now());
create table approval_tokens(jti uuid primary key, header_id uuid not null references purchase_headers(id), approver_email text not null, level int not null, action text not null, expires_at timestamptz not null, used_at timestamptz);
create or replace function is_admin() returns boolean language sql stable as $$ select exists(select 1 from users_profile where id=auth.uid() and role='admin') $$;
create or replace function is_assigned_approver(h purchase_headers) returns boolean language sql stable as $$ select exists(select 1 from approval_matrix m where m.department=h.department and m.approval_level=h.current_level and lower(m.approver_email)=lower(coalesce(auth.email(),''))) $$;
alter table purchase_headers enable row level security; alter table purchase_line_items enable row level security; alter table approval_logs enable row level security; alter table approval_matrix enable row level security; alter table email_queue enable row level security; alter table users_profile enable row level security;
create policy ph_select on purchase_headers for select using (requester_id=auth.uid() or is_admin() or is_assigned_approver(purchase_headers));
create policy ph_insert on purchase_headers for insert with check (requester_id=auth.uid());
create policy ph_update on purchase_headers for update using (is_admin() or (requester_id=auth.uid() and status in('DRAFT','CLARIFICATION_REQUIRED'))) with check (is_admin() or (requester_id=auth.uid() and status in('DRAFT','CLARIFICATION_REQUIRED')));
create policy li_all on purchase_line_items using (exists(select 1 from purchase_headers h where h.id=header_id and (h.requester_id=auth.uid() or is_admin() or is_assigned_approver(h)))) with check (exists(select 1 from purchase_headers h where h.id=header_id and (h.requester_id=auth.uid() or is_admin()) and h.status in('DRAFT','CLARIFICATION_REQUIRED')));
create policy logs_select on approval_logs for select using (is_admin() or exists(select 1 from purchase_headers h where h.id=header_id and (h.requester_id=auth.uid() or is_assigned_approver(h))));
create policy admin_all_matrix on approval_matrix using (is_admin()) with check (is_admin());
create policy profiles_own on users_profile for select using (id=auth.uid() or is_admin());
create index on purchase_headers(requester_id,status); create index on approval_matrix(department,approval_level); create index on approval_logs(header_id,timestamp);
